--
-- Structure for view `v_fee_balances`
--
DROP TABLE IF EXISTS `v_fee_balances`;

CREATE ALGORITHM=UNDEFINED DEFINER=`curac`@`localhost` SQL SECURITY DEFINER VIEW `v_fee_balances`  AS SELECT `s`.`id` AS `student_id`, `s`.`regnumber` AS `reg_number`, concat(`s`.`fname`,' ',`s`.`lname`) AS `full_name`, `s`.`program` AS `program`, `s`.`sponsor` AS `sponsor`, ifnull(sum(`i`.`amount_due`),0) AS `total_invoiced`, ifnull(sum(`i`.`amount_paid`),0) AS `total_paid`, ifnull(sum(`i`.`bursary_amount`),0) AS `total_bursary`, ifnull(sum(`i`.`amount_due`),0) - ifnull(sum(`i`.`amount_paid`),0) - ifnull(sum(`i`.`bursary_amount`),0) AS `balance_due`, if(ifnull(sum(`i`.`amount_due`),0) - ifnull(sum(`i`.`amount_paid`),0) - ifnull(sum(`i`.`bursary_amount`),0) <= 0,'Cleared','Pending') AS `clearance_status` FROM (`student` `s` left join `fee_invoices` `i` on(`s`.`id` = `i`.`student_id`)) GROUP BY `s`.`id` ;

-- --------------------------------------------------------

--
-- Structure for view `v_monthly_collections`
--
DROP TABLE IF EXISTS `v_monthly_collections`;

CREATE ALGORITHM=UNDEFINED DEFINER=`curac`@`localhost` SQL SECURITY DEFINER VIEW `v_monthly_collections`  AS SELECT date_format(`fee_payments`.`paid_at`,'%Y-%m') AS `month_label`, `fee_payments`.`payment_method` AS `payment_method`, sum(`fee_payments`.`amount`) AS `total_collected` FROM `fee_payments` WHERE `fee_payments`.`status` = 'confirmed' GROUP BY date_format(`fee_payments`.`paid_at`,'%Y-%m'), `fee_payments`.`payment_method` ;

-- --------------------------------------------------------

--
-- Structure for view `v_payroll_statutory`
--
DROP TABLE IF EXISTS `v_payroll_statutory`;

CREATE ALGORITHM=UNDEFINED DEFINER=`curac`@`localhost` SQL SECURITY DEFINER VIEW `v_payroll_statutory`  AS SELECT `hr_payroll`.`pay_month` AS `pay_month`, sum(`hr_payroll`.`gross`) AS `total_gross`, sum(`hr_payroll`.`tax`) AS `total_paye_withheld`, sum(`hr_payroll`.`pension`) AS `employee_pension`, sum(`hr_payroll`.`employer_pension`) AS `employer_pension`, sum(`hr_payroll`.`cbhi`) AS `employee_cbhi`, sum(`hr_payroll`.`employer_cbhi`) AS `employer_cbhi`, sum(`hr_payroll`.`maternity`) AS `employee_maternity`, sum(`hr_payroll`.`employer_maternity`) AS `employer_maternity`, sum(`hr_payroll`.`net`) AS `total_net_paid` FROM `hr_payroll` WHERE `hr_payroll`.`status` = 'Paid' GROUP BY `hr_payroll`.`pay_month` ;
COMMIT;

